query:
UPDATE news SET blocks = '[{"type": "text", "content": "April 2024 — The season is set at Okoboji Summer Theatre, and I'm excited to share the four productions I'll be designing this summer."}, {"type": "text", "content": "Baskerville: A Sherlock Holmes Mystery - Directed by Stephen Brotebeck - July 2–7, 2024"}, {"type": "text", "content": "Freaky Friday - Directed by Josh Walden - July 9–14, 2024"}]' WHERE id = 17;

UPDATE news SET blocks = '[{"type": "text", "content": "August 5, 2023 — I just opened my 40th production at Okoboji Summer Theatre. I'm 38 now, and somehow this has become my 15th season here."}, {"type": "text", "content": "Two people in particular have been there every single summer with me: Michael Burke, Director of Production, and Ruth Ann Burke, Executive Director."}, {"type": "text", "content": "It's surreal to look back — 40 productions is a milestone I couldn't have imagined when I first arrived here."}]' WHERE id = 5;

UPDATE news SET blocks = '[{"type": "text", "content": "November 2018 — I designed the scenic world for UC Irvine's production of Green Day's American Idiot, directed by Myrona DeLaney."}, {"type": "text", "content": "The Show Report celebrated the intensity of the performance and acknowledged the design team's contributions."}, {"type": "text", "content": "The production called for an environment that felt raw, gritty, and adaptable."}]' WHERE id = 28;

UPDATE news SET blocks = '[{"type": "text", "content": "April 25, 2023 — We began previews for my first Off-Broadway production, The Fears, assisting scenic designer Jo Winiarski."}, {"type": "text", "content": "The Fears premiered at the Irene Diamond Stage at the Pershing Square Signature Center with previews starting April 25, 2023."}, {"type": "text", "content": "Working under Jo's mentorship gave me firsthand insight into the pace and precision of Off-Broadway design."}]' WHERE id = 19;

UPDATE news SET blocks = '[{"type": "text", "content": "August 28, 2025 — Tonight marked the opening of The Play That Goes Wrong at Seattle Rep, and I'm proud to say I served as an Assistant to scenic designer Tom Buderwitz."}, {"type": "text", "content": "The show runs in the Bagley Wright Theater from August 28 through September 28, 2025."}, {"type": "text", "content": "Working with him has always felt like a master class in crafting comedic mayhem with technical precision."}]' WHERE id = 4;

